"""Head-to-head optimizer race on a fixed regression task.

Implements SGD, SGD+momentum, and Adam from scratch in numpy and trains
an identical 2-32-1 tanh MLP on y = x1^2 + x2^2 + noise, full-batch MSE.
"""

import numpy as np

# ---------------- data ----------------

def make_data(n=200, seed=2):
    rng = np.random.default_rng(seed)
    X = rng.uniform(-1.5, 1.5, size=(n, 2))
    y = (X[:, 0] ** 2 + X[:, 1] ** 2).reshape(-1, 1)
    y += rng.normal(0.0, np.sqrt(0.05), size=y.shape)  # noise(0,0.05): var 0.05
    return X.astype(np.float64), y.astype(np.float64)

# ---------------- network ----------------

class Net:
    """2 -> 32 -> 1 network: tanh hidden layer, linear output."""

    def __init__(self, seed=0):
        rng = np.random.default_rng(seed)
        self.params = {
            "W1": rng.normal(0.0, np.sqrt(2.0 / 2), size=(2, 32)),
            "b1": np.zeros((1, 32)),
            "W2": rng.normal(0.0, np.sqrt(2.0 / 32), size=(32, 1)),
            "b2": np.zeros((1, 1)),
        }

    def forward(self, X):
        p = self.params
        z1 = X @ p["W1"] + p["b1"]
        h = np.tanh(z1)
        out = h @ p["W2"] + p["b2"]
        cache = (X, z1, h)
        return out, cache

    def loss(self, pred, y):
        d = pred - y
        return float(np.mean(d * d))

    def backward(self, cache, pred, y):
        X, z1, h = cache
        n = X.shape[0]
        d_out = 2.0 * (pred - y) / n          # (n,1) grad of mean squared error
        grads = {}
        grads["W2"] = h.T @ d_out
        grads["b2"] = d_out.sum(axis=0, keepdims=True)
        dh = d_out @ self.params["W2"].T
        dz1 = dh * (1.0 - np.tanh(z1) ** 2)
        grads["W1"] = X.T @ dz1
        grads["b1"] = dz1.sum(axis=0, keepdims=True)
        return grads

# ---------------- optimizers ----------------

class SGD:
    def __init__(self, params, lr):
        self.lr = lr

    def step(self, params, grads):
        for k in params:
            params[k] -= self.lr * grads[k]


class SGDMomentum:
    def __init__(self, params, lr, momentum=0.9):
        self.lr = lr
        self.momentum = momentum
        self.v = {k: np.zeros_like(v) for k, v in params.items()}

    def step(self, params, grads):
        for k in params:
            self.v[k] = self.momentum * self.v[k] - self.lr * grads[k]
            params[k] += self.v[k]


class Adam:
    def __init__(self, params, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        self.lr, self.b1, self.b2, self.eps = lr, beta1, beta2, eps
        self.m = {k: np.zeros_like(v) for k, v in params.items()}
        self.v = {k: np.zeros_like(v) for k, v in params.items()}
        self.t = 0

    def step(self, params, grads):
        self.t += 1
        for k in params:
            g = grads[k]
            self.m[k] = self.b1 * self.m[k] + (1 - self.b1) * g
            self.v[k] = self.b2 * self.v[k] + (1 - self.b2) * g * g
            m_hat = self.m[k] / (1 - self.b1 ** self.t)
            v_hat = self.v[k] / (1 - self.b2 ** self.t)
            params[k] -= self.lr * m_hat / (np.sqrt(v_hat) + self.eps)

# ---------------- training loop ----------------

def train(optimizer_name, max_iters=3000, threshold=None, seed=0):
    """Train the fixed net; returns (losses list, iterations to reach threshold or None)."""
    X, y = make_data()
    net = Net(seed=seed)
    params = net.params
    lrs = {"sgd": 0.01, "momentum": 0.01, "adam": 0.005}
    if optimizer_name == "sgd":
        opt = SGD(params, lr=lrs["sgd"])
    elif optimizer_name == "momentum":
        opt = SGDMomentum(params, lr=lrs["momentum"], momentum=0.9)
    elif optimizer_name == "adam":
        opt = Adam(params, lr=lrs["adam"], beta1=0.9, beta2=0.999, eps=1e-8)
    else:
        raise ValueError(f"unknown optimizer: {optimizer_name}")

    losses = []
    iters_to_threshold = None
    for it in range(max_iters):
        pred, cache = net.forward(X)
        loss = net.loss(pred, y)
        losses.append(loss)
        if not np.isfinite(losses).all():
            raise FloatingPointError("non-finite loss encountered")
        if iters_to_threshold is None and threshold is not None and loss < threshold:
            iters_to_threshold = it + 1
        grads = net.backward(cache, pred, y)
        opt.step(params, grads)

    pred, _ = net.forward(X)
    losses.append(net.loss(pred, y))  # final loss after last update
    if iters_to_threshold is None and threshold is not None and losses[-1] < threshold:
        iters_to_threshold = len(losses)
    return losses, iters_to_threshold


def save_loss_csv(losses, path):
    with open(path, "w") as f:
        f.write("iteration,loss\n")
        for i, l in enumerate(losses):
            f.write(f"{i},{l!r}\n")

