import numpy as np
import pytest

import opt_race


OPTIMIZERS = ["sgd", "momentum", "adam"]
THRESHOLD = 0.02


@pytest.fixture(scope="module")
def results():
    out = {}
    for name in OPTIMIZERS:
        losses, iters = opt_race.train(name, max_iters=3000, threshold=THRESHOLD)
        out[name] = {"losses": losses, "iters": iters}
        opt_race.save_loss_csv(losses, f"loss_curve_{name}.csv")
    return out


def test_all_reach_low_mse(results):
    for name in OPTIMIZERS:
        final = results[name]["losses"][-1]
        assert np.isfinite(final), f"{name}: non-finite final loss"
        assert final < THRESHOLD, f"{name}: final MSE {final:.4f} >= {THRESHOLD}"


def test_adam_at_least_twice_as_fast_as_sgd(results):
    sgd_iters = results["sgd"]["iters"]
    adam_iters = results["adam"]["iters"]
    assert sgd_iters is not None, "SGD never crossed the threshold"
    assert adam_iters is not None, "Adam never crossed the threshold"
    assert adam_iters <= sgd_iters / 2, (
        f"Adam took {adam_iters} iters vs SGD {sgd_iters} "
        f"(needs <= half)"
    )


@pytest.mark.parametrize("name", OPTIMIZERS)
def test_loss_curves_finite(results, name):
    losses = np.asarray(results[name]["losses"])
    assert len(losses) > 0
    assert np.isfinite(losses).all(), f"{name}: NaN/inf in loss curve"


@pytest.mark.parametrize("name", OPTIMIZERS)
def test_csv_written(name):
    import csv

    with open(f"loss_curve_{name}.csv") as f:
        rows = list(csv.DictReader(f))
    assert rows
    vals = [float(r["loss"]) for r in rows]
    assert all(np.isfinite(vals))

